// Selección normal por registry. Override histórico sólo en dry-run manual.
const request = { course: 'PWA', manualCourseWorkOverride: null, bootstrapHistorical: false };
return [{ json: { ...request, triggerKind: 'manual', attempt: 1 } }];

const course = String($json.course || '').trim().toUpperCase();
const config = {
  PWA: { courseId: $env.CLASSROOM_PWA_COURSE_ID, repository: $env.PWA_REPOSITORY || 'Draggodeidad/pwa-utt' },
  DMI: { courseId: $env.CLASSROOM_DMI_COURSE_ID, repository: $env.DMI_REPOSITORY || 'Draggodeidad/campusops-dmi-team' },
};
if (!config[course]?.courseId) throw new Error(`Falta configuración Classroom para ${course}`);
if ($json.week != null) throw new Error('Usa manualCourseWorkOverride; la semana sólo es metadata.');
const triggerKind = $json.triggerKind;
if (!['manual', 'schedule'].includes(triggerKind)) throw new Error('Trigger desconocido');
const manualCourseWorkOverride = String($json.manualCourseWorkOverride || '').trim() || null;
if (manualCourseWorkOverride && (triggerKind !== 'manual' || String($env.AUTOMATION_MODE || 'dry-run') !== 'dry-run')) {
  throw new Error('OVERRIDE_FORBIDDEN: sólo ejecución manual explícita en dry-run');
}
if ($json.bootstrapHistorical && (triggerKind !== 'manual' || manualCourseWorkOverride)) {
  throw new Error('BOOTSTRAP_FORBIDDEN: requiere ejecución manual sin override');
}
return [{ json: {
  course, courseId: String(config[course].courseId), repository: config[course].repository,
  triggerKind, attempt: Number($json.attempt || 1), manualCourseWorkOverride,
  bootstrapHistorical: $json.bootstrapHistorical === true,
  selectionStartedAt: new Date().toISOString(), automationMode: 'dry-run', mode: 'dry-run', mutationsPerformed: false,
} }];

const data = $json;
const payload = data.classroomResponse?.body ?? data.classroomResponse ?? {};
if (payload.nextPageToken) throw new Error('CLASSROOM_INCOMPLETE_SNAPSHOT: faltan páginas');
const rows = Array.isArray(payload.courseWork) ? payload.courseWork : [];
const globalState = $getWorkflowStaticData('global');
const saved = globalState.classroomRegistry?.[data.courseId];
const registry = saved ? JSON.parse(JSON.stringify(saved)) : null;
const override = data.manualCourseWorkOverride;
if (override && (data.triggerKind !== 'manual' || data.automationMode !== 'dry-run')) throw new Error('OVERRIDE_FORBIDDEN');
const weekFrom = (title) => {
  const match = String(title || '').match(/(?:\[\s*)?semana\s*0*(\d{1,2})(?:\s*\])?/i);
  return match ? Number(match[1]) : null;
};
const applicable = (cw) => cw.state === 'PUBLISHED' && weekFrom(cw.title) >= 1 && weekFrom(cw.title) <= 99 &&
  !/\b(quiz|examen|recordatorio)\b/i.test(`${cw.title || ''}`);
for (const cw of rows) {
  if (!cw.id || String(cw.courseId) !== String(data.courseId)) throw new Error('CLASSROOM_INVALID_IDENTITY');
}
const noWork = (extra) => [{ json: { ...data, mode: 'dry-run', automationMode: 'dry-run', mutationsPerformed: false,
  found: false, pendingCourseworkCount: 0, issuesThatWouldBeCreated: [], ...extra } }];
if (data.bootstrapHistorical) {
  if (registry) throw new Error('BOOTSTRAP_ALREADY_EXISTS: no se permite mover el cutover');
  const cutoverAt = data.selectionStartedAt || new Date().toISOString();
  const entries = Object.fromEntries(rows.map(cw => [String(cw.id), {
    courseWorkId: String(cw.id), state: 'ignored_historical', reason: 'present_before_automation_cutover',
    title: cw.title, observedAt: cutoverAt,
  }]));
  return noWork({ executionResult: 'no_pending_coursework', selectionMode: 'historical_bootstrap_preview',
    historicalCourseworkCount: rows.length, cutoverAt, registryPersisted: false,
    proposedRegistry: { version: 1, courseId: data.courseId, cutoverAt, entries } });
}
if (!registry && !override) return noWork({ executionResult: 'historical_bootstrap_required',
  selectionMode: 'bootstrap_required', historicalCourseworkCount: 0, registryPersisted: false });
if (registry && (registry.version !== 1 || !Number.isFinite(Date.parse(registry.cutoverAt)) || !registry.entries)) {
  throw new Error('REGISTRY_INVALID');
}
const allowedStates = new Set(['ignored_historical', 'pending', 'processing', 'processed', 'failed', 'skipped', 'superseded']);
if (registry) for (const [id, entry] of Object.entries(registry.entries)) {
  if (entry.courseWorkId !== id || !allowedStates.has(entry.state)) throw new Error('REGISTRY_INVALID');
}
const entries = registry?.entries || {};
const candidates = rows.filter(applicable).filter(cw => {
  if (override) return String(cw.id) === override;
  const state = entries[cw.id]?.state;
  return !state || state === 'pending' || state === 'failed';
});
// Creation/publication time ascending; never updateTime. Stable ID breaks ties.
const timestamp = cw => {
  for (const value of [cw.scheduledTime, cw.creationTime]) {
    const time = Date.parse(value || '');
    if (Number.isFinite(time)) return time;
  }
  return Number.MAX_SAFE_INTEGER;
};
candidates.sort((a, b) => timestamp(a) - timestamp(b) || (String(a.id) < String(b.id) ? -1 : String(a.id) > String(b.id) ? 1 : 0));
if (!override && registry) for (const cw of candidates) {
  entries[cw.id] ||= { courseWorkId: String(cw.id), state: 'pending', reason: 'new_id_after_bootstrap', observedAt: new Date().toISOString() };
}
// n8n persists static data only in successful published trigger executions; manual previews remain read-only.
if (!override && registry && data.triggerKind === 'schedule') {
  globalState.classroomRegistry[data.courseId] = registry;
}
const selection = {
  selectionMode: override ? 'manual_test_override' : 'pending_registry', cutoverAt: registry?.cutoverAt || null,
  historicalCourseworkCount: Object.values(entries).filter(x => x.state === 'ignored_historical').length,
  pendingCourseworkCount: override ? 0 : candidates.length,
  selectionOrder: 'scheduledTime || creationTime ascending, courseWorkId ascending',
};
if (!candidates.length) {
  if (override) throw new Error('OVERRIDE_NOT_APPLICABLE_OR_NOT_FOUND');
  return noWork({ ...selection, executionResult: 'no_pending_coursework' });
}
const cw = candidates[0];
const week = weekFrom(cw.title);
const dueAt = cw.dueDate ? `${cw.dueDate.year}-${String(cw.dueDate.month).padStart(2,'0')}-${String(cw.dueDate.day).padStart(2,'0')}` +
  (cw.dueTime ? `T${String(cw.dueTime.hours || 0).padStart(2,'0')}:${String(cw.dueTime.minutes || 0).padStart(2,'0')}:00` : '') : null;
return [{ json: { ...data, ...selection, found: true, executionResult: 'coursework_found',
  courseWorkId: String(cw.id), courseWorkState: entries[cw.id]?.state || 'pending',
  historicalStatus: entries[cw.id]?.state === 'ignored_historical' ? 'ignored_historical' : 'not_historical',
  week, weekPadded: String(week).padStart(2,'0'), assignmentTitle: String(cw.title || '').trim(),
  description: String(cw.description || '').slice(0,30000), materials: cw.materials || [],
  alternateLink: cw.alternateLink || null, creationTime: cw.creationTime || null, updateTime: cw.updateTime || null,
  dueAt, scheduledTime: cw.scheduledTime || null, maxPoints: cw.maxPoints ?? null, workType: cw.workType || null,
} }];

const data = $json;
const payload = data.classroomResponse?.body ?? data.classroomResponse ?? {};
if (payload.nextPageToken) throw new Error('CLASSROOM_INCOMPLETE_SNAPSHOT: faltan páginas');
const rows = Array.isArray(payload.courseWork) ? payload.courseWork : [];
const globalState = $getWorkflowStaticData('global');
const saved = globalState.classroomRegistry?.[data.courseId];
const registry = saved ? JSON.parse(JSON.stringify(saved)) : null;
const override = data.manualCourseWorkOverride;
if (override && (data.triggerKind !== 'manual' || data.automationMode !== 'dry-run')) throw new Error('OVERRIDE_FORBIDDEN');
const weekFrom = (title) => {
  const match = String(title || '').match(/(?:\[\s*)?semana\s*0*(\d{1,2})(?:\s*\])?/i);
  return match ? Number(match[1]) : null;
};
const applicable = (cw) => cw.state === 'PUBLISHED' && weekFrom(cw.title) >= 1 && weekFrom(cw.title) <= 99 &&
  !/\b(quiz|examen|recordatorio)\b/i.test(`${cw.title || ''}`);
for (const cw of rows) {
  if (!cw.id || String(cw.courseId) !== String(data.courseId)) throw new Error('CLASSROOM_INVALID_IDENTITY');
}
const noWork = (extra) => [{ json: { ...data, mode: 'dry-run', automationMode: 'dry-run', mutationsPerformed: false,
  found: false, pendingCourseworkCount: 0, issuesThatWouldBeCreated: [], ...extra } }];
if (data.bootstrapHistorical) {
  if (registry) throw new Error('BOOTSTRAP_ALREADY_EXISTS: no se permite mover el cutover');
  const cutoverAt = data.selectionStartedAt || new Date().toISOString();
  const entries = Object.fromEntries(rows.map(cw => [String(cw.id), {
    courseWorkId: String(cw.id), state: 'ignored_historical', reason: 'present_before_automation_cutover',
    title: cw.title, observedAt: cutoverAt,
  }]));
  return noWork({ executionResult: 'no_pending_coursework', selectionMode: 'historical_bootstrap_preview',
    historicalCourseworkCount: rows.length, cutoverAt, registryPersisted: false,
    proposedRegistry: { version: 1, courseId: data.courseId, cutoverAt, entries } });
}
if (!registry && !override) return noWork({ executionResult: 'historical_bootstrap_required',
  selectionMode: 'bootstrap_required', historicalCourseworkCount: 0, registryPersisted: false });
if (registry && (registry.version !== 1 || !Number.isFinite(Date.parse(registry.cutoverAt)) || !registry.entries)) {
  throw new Error('REGISTRY_INVALID');
}
const allowedStates = new Set(['ignored_historical', 'pending', 'processing', 'processed', 'failed', 'skipped', 'superseded']);
if (registry) for (const [id, entry] of Object.entries(registry.entries)) {
  if (entry.courseWorkId !== id || !allowedStates.has(entry.state)) throw new Error('REGISTRY_INVALID');
}
const entries = registry?.entries || {};
const candidates = rows.filter(applicable).filter(cw => {
  if (override) return String(cw.id) === override;
  const state = entries[cw.id]?.state;
  return !state || state === 'pending' || state === 'failed';
});
// Creation/publication time ascending; never updateTime. Stable ID breaks ties.
const timestamp = cw => {
  for (const value of [cw.scheduledTime, cw.creationTime]) {
    const time = Date.parse(value || '');
    if (Number.isFinite(time)) return time;
  }
  return Number.MAX_SAFE_INTEGER;
};
candidates.sort((a, b) => timestamp(a) - timestamp(b) || (String(a.id) < String(b.id) ? -1 : String(a.id) > String(b.id) ? 1 : 0));
if (!override && registry) for (const cw of candidates) {
  entries[cw.id] ||= { courseWorkId: String(cw.id), state: 'pending', reason: 'new_id_after_bootstrap', observedAt: new Date().toISOString() };
}
// n8n persists static data only in successful published trigger executions; manual previews remain read-only.
if (!override && registry && data.triggerKind === 'schedule') {
  globalState.classroomRegistry[data.courseId] = registry;
}
const selection = {
  selectionMode: override ? 'manual_test_override' : 'pending_registry', cutoverAt: registry?.cutoverAt || null,
  historicalCourseworkCount: Object.values(entries).filter(x => x.state === 'ignored_historical').length,
  pendingCourseworkCount: override ? 0 : candidates.length,
  selectionOrder: 'scheduledTime || creationTime ascending, courseWorkId ascending',
};
if (!candidates.length) {
  if (override) throw new Error('OVERRIDE_NOT_APPLICABLE_OR_NOT_FOUND');
  return noWork({ ...selection, executionResult: 'no_pending_coursework' });
}
const cw = candidates[0];
const week = weekFrom(cw.title);
const dueAt = cw.dueDate ? `${cw.dueDate.year}-${String(cw.dueDate.month).padStart(2,'0')}-${String(cw.dueDate.day).padStart(2,'0')}` +
  (cw.dueTime ? `T${String(cw.dueTime.hours || 0).padStart(2,'0')}:${String(cw.dueTime.minutes || 0).padStart(2,'0')}:00` : '') : null;
return [{ json: { ...data, ...selection, found: true, executionResult: 'coursework_found',
  courseWorkId: String(cw.id), courseWorkState: entries[cw.id]?.state || 'pending',
  historicalStatus: entries[cw.id]?.state === 'ignored_historical' ? 'ignored_historical' : 'not_historical',
  week, weekPadded: String(week).padStart(2,'0'), assignmentTitle: String(cw.title || '').trim(),
  description: String(cw.description || '').slice(0,30000), materials: cw.materials || [],
  alternateLink: cw.alternateLink || null, creationTime: cw.creationTime || null, updateTime: cw.updateTime || null,
  dueAt, scheduledTime: cw.scheduledTime || null, maxPoints: cw.maxPoints ?? null, workType: cw.workType || null,
} }];

const data = $json;
const normalized = (data.materials || []).map((material, index) => {
  const attachment = material.driveFile?.driveFile || material.driveFile || null;
  if (attachment?.id) {
    return {
      index,
      type: 'driveFile',
      id: String(attachment.id),
      name: String(attachment.title || attachment.name || ''),
      alternateLink: attachment.alternateLink || null,
      shareMode: material.driveFile?.shareMode || null,
    };
  }
  if (material.link) return { index, type: 'link', url: material.link.url || null, title: material.link.title || null };
  if (material.youtubeVideo) return { index, type: 'youtubeVideo', id: material.youtubeVideo.id || null, title: material.youtubeVideo.title || null };
  if (material.form) return { index, type: 'form', title: material.form.title || null, formUrl: material.form.formUrl || null };
  return { index, type: 'other', metadata: material };
});

const zipCandidates = normalized.filter((item) => item.type === 'driveFile' && /\.zip$/i.test(item.name.trim()));
const weekToken = `w${data.weekPadded}`;
const score = (item) => {
  const name = item.name.toLowerCase();
  return (name.includes(data.course.toLowerCase()) ? 4 : 0) +
    (name.includes(weekToken) || name.includes(`week-${data.weekPadded}`) || name.includes(`semana-${data.weekPadded}`) ? 4 : 0) +
    (/(starter|kit-estudiante|student)/i.test(name) ? 2 : 0);
};
const ranked = zipCandidates.map((item) => ({ item, score: score(item) })).sort((a, b) => b.score - a.score);
if (ranked.length > 1 && ranked[0].score === ranked[1].score) {
  throw new Error(`Hay múltiples ZIP ambiguos: ${ranked.map(({ item }) => item.name).join(', ')}`);
}
const selected = ranked[0]?.item || null;

return [{
  json: {
    ...data,
    materialInventory: normalized,
    starterFound: Boolean(selected),
    starterDriveFileId: selected?.id || null,
    starterName: selected?.name || null,
  },
}];

return [{
  json: {
    ...$json,
    starter: {
      found: false,
      name: null,
      driveFileId: null,
      fileCount: 0,
      files: [],
      relevantFiles: [],
      requiredFiles: [],
      instructions: [],
      commands: [],
      acceptanceCriteria: [],
      tests: [],
      constraints: [],
      rubric: [],
      potentialConflicts: [],
    },
  },
}];

const data = $json;
const metadata = data.driveMetadata?.body ?? data.driveMetadata ?? {};
if (!metadata.id) throw new Error("DriveFile inexistente o inaccesible");
if (metadata.capabilities?.canDownload !== true)
  throw new Error(`Drive no permite descargar ${data.starterName}`);
if (!/\.zip$/i.test(metadata.name || data.starterName || ""))
  throw new Error("El starter seleccionado no tiene extensión .zip");
const maxBytes = Number($env.MAX_ZIP_SIZE_MB || 25) * 1024 * 1024;
if (Number(metadata.size || 0) > maxBytes)
  throw new Error(`ZIP excede MAX_ZIP_SIZE_MB (${metadata.size} bytes)`);
return [
  {
    json: {
      ...data,
      driveFile: metadata,
      starterName: metadata.name || data.starterName,
    },
  },
];

const data = $json;
const inputField = Object.keys($binary || {})[0];
if (!inputField) throw new Error('Drive no devolvió contenido binario para el ZIP');
const buffer = await this.helpers.getBinaryDataBuffer(0, inputField);
const maxZip = Number($env.MAX_ZIP_SIZE_MB || 25) * 1024 * 1024;
const maxExtracted = Number($env.MAX_EXTRACTED_SIZE_MB || 100) * 1024 * 1024;
const maxFiles = Number($env.MAX_ZIP_FILES || 500);
const maxSingle = Number($env.MAX_SINGLE_FILE_MB || 10) * 1024 * 1024;
if (buffer.length > maxZip) throw new Error(`ZIP excede el límite de ${maxZip} bytes`);
if (buffer.length < 22 || buffer.readUInt32LE(0) !== 0x04034b50) throw new Error('ZIP corrupto o firma local inválida');

let eocd = -1;
for (let i = buffer.length - 22; i >= Math.max(0, buffer.length - 65557); i -= 1) {
  if (buffer.readUInt32LE(i) === 0x06054b50) { eocd = i; break; }
}
if (eocd < 0) throw new Error('ZIP corrupto: no se encontró el directorio central');
const entryCount = buffer.readUInt16LE(eocd + 10);
const centralSize = buffer.readUInt32LE(eocd + 12);
const centralOffset = buffer.readUInt32LE(eocd + 16);
if (entryCount > maxFiles) throw new Error(`ZIP contiene ${entryCount} archivos; máximo ${maxFiles}`);
if (centralOffset + centralSize > eocd) throw new Error('ZIP corrupto: directorio central fuera de rango');

const entries = [];
let cursor = centralOffset;
let totalUncompressed = 0;
for (let index = 0; index < entryCount; index += 1) {
  if (cursor + 46 > buffer.length || buffer.readUInt32LE(cursor) !== 0x02014b50) throw new Error('ZIP corrupto: entrada central inválida');
  const flags = buffer.readUInt16LE(cursor + 8);
  const compressedSize = buffer.readUInt32LE(cursor + 20);
  const uncompressedSize = buffer.readUInt32LE(cursor + 24);
  const nameLength = buffer.readUInt16LE(cursor + 28);
  const extraLength = buffer.readUInt16LE(cursor + 30);
  const commentLength = buffer.readUInt16LE(cursor + 32);
  const externalAttributes = buffer.readUInt32LE(cursor + 38);
  const nameStart = cursor + 46;
  const name = buffer.subarray(nameStart, nameStart + nameLength).toString((flags & 0x800) ? 'utf8' : 'latin1').replace(/\\/g, '/');
  const segments = name.split('/');
  const unixMode = (externalAttributes >>> 16) & 0xffff;
  const isSymlink = (unixMode & 0xf000) === 0xa000;
  if (!name || name.includes('\0') || name.startsWith('/') || /^[a-z]:\//i.test(name) || segments.includes('..')) throw new Error(`ZIP Slip/path inseguro: ${name}`);
  if (isSymlink) throw new Error(`ZIP contiene symlink no permitido: ${name}`);
  if (flags & 0x1) throw new Error(`ZIP cifrado no soportado: ${name}`);
  if (uncompressedSize > maxSingle) throw new Error(`Archivo excede MAX_SINGLE_FILE_MB: ${name}`);
  if (compressedSize > 0 && uncompressedSize / compressedSize > 100) throw new Error(`Posible compression bomb: ${name}`);
  totalUncompressed += uncompressedSize;
  if (totalUncompressed > maxExtracted) throw new Error('ZIP excede MAX_EXTRACTED_SIZE_MB');
  entries.push({ path: name, compressedSize, uncompressedSize, directory: name.endsWith('/') });
  cursor = nameStart + nameLength + extraLength + commentLength;
}

return [{
  json: {
    ...data,
    zipValidation: { compressedBytes: buffer.length, extractedBytes: totalUncompressed, fileCount: entries.filter((e) => !e.directory).length, entries },
  },
  binary: $binary,
}];

const data = $json;
const binaries = $binary || {};
const maxFiles = Number($env.MAX_ZIP_FILES || 500);
const maxSingle = Number($env.MAX_SINGLE_FILE_MB || 10) * 1024 * 1024;
const entries = Object.entries(binaries).map(([field, meta]) => ({ field, meta, path: String(meta.fileName || field).replace(/\\/g, '/') }));
if (entries.length > maxFiles) throw new Error(`Extracción produjo ${entries.length} archivos; máximo ${maxFiles}`);
for (const entry of entries) {
  if (entry.path.startsWith('/') || /^[a-z]:\//i.test(entry.path) || entry.path.split('/').includes('..')) throw new Error(`Ruta extraída insegura: ${entry.path}`);
}

const priority = (path) => {
  const name = path.toLowerCase();
  if (/(activity_student_facing|starter_and_repository|rubric_public|readme)\.md$/.test(name)) return 100;
  if (/(requirements|instructions|activity|rubric).*\.md$/.test(name)) return 90;
  if (/(^|\/)(package\.json|makefile)$/.test(name)) return 80;
  if (/\.github\/workflows\//.test(name) || /(^|\/)(tests?|specs?)\//.test(name)) return 75;
  if (/(tsconfig|eslint|vite|next|expo|app\.json)/.test(name)) return 65;
  if (/\.(md|txt|json|ya?ml|toml|js|mjs|cjs|ts|tsx|jsx|py|java|kt|swift|go|rs|css|html|sql|sh)$/.test(name)) return 20;
  return 0;
};
const selected = entries.filter((entry) => priority(entry.path) > 0).sort((a, b) => priority(b.path) - priority(a.path) || a.path.localeCompare(b.path));
const relevantFiles = [];
let contextBytes = 0;
const maxContextBytes = 220000;
for (const entry of selected) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, entry.field);
  if (buffer.length > maxSingle || contextBytes >= maxContextBytes) continue;
  const slice = buffer.subarray(0, Math.min(buffer.length, 64000, maxContextBytes - contextBytes));
  if (slice.includes(0)) continue;
  const content = slice.toString('utf8');
  contextBytes += Buffer.byteLength(content);
  relevantFiles.push({ path: entry.path, content, truncated: slice.length < buffer.length });
}
const corpus = relevantFiles.map((file) => `# ${file.path}\n${file.content}`).join('\n');
const lines = corpus.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
const unique = (values, limit = 40) => [...new Set(values)].slice(0, limit);
const commands = unique(lines.filter((line) => /^(?:\$\s*)?(npm|pnpm|yarn|bun|npx|make|docker|go\s+test|pytest|mvn|gradle|swift\s+test)\b/i.test(line)).map((line) => line.replace(/^\$\s*/, '')));
const acceptanceCriteria = unique(lines.filter((line) => /^[-*]\s*\[[ xX]\]/.test(line)).map((line) => line.replace(/^[-*]\s*\[[ xX]\]\s*/, '')));
const constraints = unique(lines.filter((line) => /\b(no\s+(?:modificar|eliminar|usar)|debe|obligatorio|restricci[oó]n|prohibido|conservar|preservar)\b/i.test(line)));
const rubric = unique(lines.filter((line) => /\b(r[uú]brica|puntos?|criterio|excelente|satisfactorio)\b/i.test(line)));
const requiredFiles = unique(lines.flatMap((line) => [...line.matchAll(/`([^`]+\.[a-z0-9]+)`/gi)].map((match) => match[1])));
const tests = unique(entries.map((entry) => entry.path).filter((path) => /(^|\/)(tests?|specs?)\/|\.(test|spec)\.[^.]+$/i.test(path)));

return [{
  json: {
    ...data,
    starter: {
      found: true,
      name: data.starterName,
      driveFileId: data.starterDriveFileId,
      fileCount: entries.length,
      files: entries.map((entry) => entry.path).sort(),
      relevantFiles,
      requiredFiles,
      instructions: unique(lines.filter((line) => /^(?:\d+\.|[-*])\s+/.test(line))),
      commands,
      acceptanceCriteria,
      tests,
      constraints,
      rubric,
      potentialConflicts: [],
      security: data.zipValidation,
    },
  },
}];

const context = $('Activity Context').item.json;
const tree = $('GitHub - Tree').item.json.body || {};
if (tree.truncated) throw new Error('REPOSITORY_INCOMPLETE_TREE');
const source = `${context.description || ''} ${(context.starter?.files || []).join(' ')}`;
const files = (tree.tree || []).filter(file => file.type === 'blob' && file.size <= 100000 &&
  /\.(md|txt|json|[cm]?js|ts|tsx|jsx|html|css|ya?ml)$/i.test(file.path) &&
  !/(^|\/)(node_modules|vendor|dist|\.env|package-lock|pnpm-lock|yarn.lock)/i.test(file.path));
files.sort((a, b) => Number(source.includes(b.path)) - Number(source.includes(a.path)) ||
  Number(/requirements|individual|evidence|rubric/i.test(b.path)) - Number(/requirements|individual|evidence|rubric/i.test(a.path)) || a.path.localeCompare(b.path));
const selected = files.slice(0, 20);
// README is also a safe fallback so an empty tree still advances to Build Context.
