    if (!String(issue.title || "").startsWith(`${prefix} `))
      addError("INVALID_TITLE", `${where}: title sin prefijo ${prefix}`, false);
    const semanticTitle = String(issue.title || "").replace(
      /^\s*\[[A-Za-z0-9]+\]\[W\d{1,2}\]\s*/,
      "",
    );
    if (seenTitles.has(semanticTitle))
      addError(
        "DUPLICATE_TITLE",
