    "Inconsistencia interna: schemaStatus=valid no puede producir SCHEMA_ERROR",
    false,
    { kind: "validator" },
  );
  valid = false;
}
const provenanceDetected = errors.some((error) => error.kind === "provenance");
const groundingDetected = errors.some((error) => error.kind === "grounding");
const dependencyDetected = errors.some((error) => error.kind === "dependency");
const semanticDetected = errors.some((error) => !error.kind);

let errorType;
if (hasParseIssue) errorType = data.errorType || "SCHEMA_ERROR";
else if (internalDetected) errorType = "VALIDATOR_INTERNAL_ERROR";
else if (provenanceDetected) errorType = "PROVENANCE_ERROR";
else if (groundingDetected) errorType = "GROUNDING_ERROR";
else if (dependencyDetected) errorType = "DEPENDENCY_ERROR";
else if (semanticDetected) errorType = "SEMANTIC_ERROR";
else errorType = valid ? "VALID" : "SCHEMA_ERROR";

const statuses = {
  transportStatus: data.normalizedResponse?.transportStatus || "not_attempted",
  providerStatus: data.normalizedResponse?.providerStatus || "not_attempted",
  parseStatus: data.parseStatus || "not_attempted",
  schemaStatus: data.schemaStatus || "not_attempted",
  groundingStatus:
    provenanceDetected || groundingDetected
      ? "invalid"
      : hasParseIssue ? "not_attempted" : "valid",
  semanticStatus: semanticDetected
    ? "invalid"
    : hasParseIssue ? "not_attempted" : "valid",
  dependencyStatus: dependencyDetected
    ? "invalid"
    : hasParseIssue ? "not_attempted" : "valid",
  finalPlanStatus: valid ? "accepted" : "rejected",
};

const failureReason = valid ? null : {
  errorType,
  provider: data.llmAttempt?.provider || null,
  model: data.llmAttempt?.model || null,
  httpStatus: data.normalizedResponse?.httpStatus ?? null,
  message: data.normalizedResponse?.error || errors.map((error) => error.message).join("; "),
  ...(["PARSE_ERROR", "SCHEMA_ERROR"].includes(errorType)
    ? { validationErrors: errors.map((error) => error.message) } : {}),
  ...(["GROUNDING_ERROR", "PROVENANCE_ERROR"].includes(errorType)
    ? {
        validationErrors: errors.map((error) => error.message),
        groundingErrors: errors
          .filter((error) => ["grounding", "provenance"].includes(error.kind))
          .map((error) => ({
            issueKey: error.issueKey,
            detail: error.detail,
            reason: error.reason,
            sourceId: error.sourceId || null,
          })),
      }
    : {}),
  ...(errorType === "VALIDATOR_INTERNAL_ERROR"
    ? {
        message: "Provenance resoluble ignorado por el validator",
        details: errors
          .filter((error) => error.kind === "validator")
          .map((error) => ({
            issueKey: error.issueKey,
            detail: error.detail,
            matchedSourceId: error.sourceId || null,
            message: error.message,
          })),
      }
    : {}),
};
const stage = data.llmAttempt?.stage || 'gemini';
const repairUsed = Boolean(data.repairUsed);
const fallbackUsed = ['qwen', 'glm'].includes(stage);
const REPAIRABLE = new Set([
  'PARSE_ERROR', 'SCHEMA_ERROR', 'GROUNDING_ERROR', 'PROVENANCE_ERROR',
  'SEMANTIC_ERROR', 'DEPENDENCY_ERROR',
]);
const transitions = { gemini_repair: 'QWEN_REQUEST', qwen: 'GLM_REQUEST', glm: 'FAIL_CLOSED' };
let nextState;
if (valid) nextState = 'PLAN_VALID';
else if (errorType === 'VALIDATOR_INTERNAL_ERROR') nextState = 'FAIL_VALIDATOR';
else if (stage === 'gemini') nextState = !repairUsed && REPAIRABLE.has(errorType)
  ? 'GEMINI_REPAIR_REQUEST' : 'QWEN_REQUEST';
else nextState = transitions[stage];
if (!nextState) throw new Error('AI_STATE_INVALID: transición desconocida');
const normalizedResponse = {
  ...(data.normalizedResponse || {}),
  success: valid,
  error: failureReason?.message || null,
  errorType,
  failureReason,
  validationStatus: valid ? 'valid' : 'invalid',
  ...statuses,
  groundingReport,
};
const stateHistory = [...(data.stateHistory || [])];
if (!hasParseIssue && data.schemaStatus === 'valid')
  stateHistory.push(`${String(stage).toUpperCase()}_GROUNDING_VALIDATE`);
if (['PLAN_VALID', 'FAIL_CLOSED', 'FAIL_VALIDATOR'].includes(nextState))
  stateHistory.push(nextState);
const observation = {
  provider: normalizedResponse.provider || data.llmAttempt?.provider || null,
  model: normalizedResponse.model || data.llmAttempt?.model || null,
  stage: stage === 'gemini' ? 'initial' : stage === 'gemini_repair' ? 'repair' : stage,
  httpStatus: normalizedResponse.httpStatus ?? null,
  result: errorType.toLowerCase(), errorType, success: valid,
  ...statuses,
  validationStatus: normalizedResponse.validationStatus,
  repairUsed, fallbackUsed, failureReason,
  providerError: normalizedResponse.providerError || null,
  durationMs: normalizedResponse.durationMs ?? null,
  identifierNormalizations: data.identifierNormalizations || [],
  groundingReport,
};
const aiObservability = [...(data.aiObservability || []), observation];
const aiExecution = {
  requestedProvider: 'gemini',
  resolvedProvider: valid ? observation.provider : null,
  resolvedModel: valid ? observation.model : null,
  repairUsed, fallbackUsed,
};
return [{ json: {
  ...data, valid, retryable: false, errorType, failureReason, nextState,
  llmState: nextState, stateHistory, repairUsed, fallbackUsed,
  validationErrors: errors, normalizedResponse, aiObservability, aiExecution,
  ...statuses, groundingReport,
  mode: 'dry-run', automationMode: 'dry-run', mutationsPerformed: false,
} }];

const data = $json;
const plan = JSON.parse(JSON.stringify(data.plan));
const members = ['Draggodeidad', 'JulianDele', 'osbaldoXxC'];
const personalPattern = /evidencia individual|aportaci[oó]n individual|cada (?:integrante|persona|miembro)/i;
const negative = /\bno\s+(?:(?:se\s+)?(?:requiere|pide|exige|solicita)\s+)?(?:evidencia individual|aportaci[oó]n individual)/i;
const sources = Object.entries(data.groundingCatalog || {}).filter(([, entry]) => ['classroom', 'starter'].includes(entry.source));
const requirements = sources.flatMap(([id, entry]) => {
  const lines = String(entry.content).split('\n');
  const found = [];
  for (let i = 0; i < lines.length; i++) {
    const text = lines[i].trim();
    if (!personalPattern.test(text) || negative.test(text) ||
      !/evidencia|aportaci[oó]n|contribuci[oó]n|documentar|registrar/i.test(text)) continue;
    found.push({ id, source: entry.source, text });
    // Preserve source-defined fields in a following rubric/list; do not invent fields.
    for (let j = i + 1; j < lines.length && /^\s*(?:[-*+]|\d+[.)])\s+/.test(lines[j]); j++) {
      found.push({ id, source: entry.source, text: lines[j].trim() });
    }
  }
  return found;
});
if (!requirements.length) return [{ json: { ...data, personalRequirementsRequired: false } }];
const templates = plan.issues.filter(issue => ['evidence', 'documentation'].includes(issue.category) &&
  personalPattern.test(issue.title));
const removed = new Set(templates.map(issue => issue.key));
plan.issues = plan.issues.filter(issue => !removed.has(issue.key));
const keys = members.map(member => `evidence-${member.toLowerCase()}`);
if (plan.issues.some(issue => keys.includes(issue.key))) throw new Error('PLAN_INVALID: personal evidence key collision');
for (const issue of plan.issues) issue.dependsOn = [...new Set((issue.dependsOn || []).flatMap(key => removed.has(key) ? keys : [key]))];
const completePersonalEvidence = [];
for (const member of members) {
  const criteria = [...new Set(requirements.map(requirement => requirement.text))];
  const template = templates[0];
  const review = data.coverageReview?.[`evidence-${member.toLowerCase()}`];
  const checks = criteria.map(requirement => {
    const proof = review?.requirementsChecked?.find(check => check.requirement === requirement);
    const file = proof && data.repositoryContents?.[proof.path];
    const satisfied = Boolean(review?.reviewedBy && proof?.satisfied === true && proof.personalOwner === member &&
      file?.sha === proof.blobSha && file?.sha && !file.truncated &&
      String(proof.excerpt || '').trim().length >= 20 && file.content.includes(proof.excerpt) &&
      !/\b(TODO|TBD|placeholder|pendiente)\b/i.test(proof.excerpt));
    return { requirement, satisfied, evidence: satisfied ? `repository.path:${proof.path}` : null,
      ...(satisfied ? { excerpt: proof.excerpt, blobSha: proof.blobSha, reviewedBy: review.reviewedBy, personalOwner: member } : {}) };
  });
  if (checks.length && checks.every(check => check.satisfied)) {
    completePersonalEvidence.push({ key: `evidence-${member.toLowerCase()}`, member, status: 'complete', requirementsChecked: checks });
    continue;
  }
  const pendingCriteria = checks.filter(check => !check.satisfied).map(check => check.requirement);
  const sections = {
    historiaUsuario: `Como integrante ${member}, quiero documentar MI contribución para cumplir la evidencia individual solicitada.`,
    contexto: `Responsabilidad exclusiva de ${member}. Registrar únicamente mi propia contribución.`,
    objetivoTecnico: pendingCriteria, alcance: pendingCriteria, fueraDeAlcance: ['Completar evidencia de otros integrantes.'],
    archivosEsperados: template?.sections?.archivosEsperados || [], pasosSugeridos: pendingCriteria,
    criteriosAceptacion: pendingCriteria, pruebas: ['Verificar mi evidencia contra los requisitos citados.'], dependencias: [],
    evidenciaIndividual: pendingCriteria, definitionOfDone: pendingCriteria,
  };
  plan.issues.push({ key: `evidence-${member.toLowerCase()}`,
    title: `[${data.course}][W${data.weekPadded}] Evidencia individual — ${member}`,
    category: 'individual-evidence', type: 'evidence', priority: 'medium', difficulty: 'easy', estimatedWeight: 1,
    risk: 'low', requiresCoding: false, requiresRepositoryKnowledge: false,
    requirementKind: 'sourceRequirement', personalRequirement: true, delegable: false, personalOwner: member,
    assignee: member, dependsOn: [], sections,
    gapAnalysis: { status: checks.some(check => check.satisfied) ? 'partial' : 'missing', summary: 'La responsabilidad personal requiere cobertura verificada por integrante.',
      evidence: [...new Set(requirements.map(r => r.id))], requirementsChecked: checks },
    provenance: requirements.map(r => ({ claim: r.text, source: r.source, evidence: r.id })),
    groundingStatus: 'grounded', personalSourceRequirements: requirements,
  });
}
for (const issue of plan.issues) {
  issue.dependsOn = (issue.dependsOn || []).filter(key => {
    const done = completePersonalEvidence.find(entry => entry.key === key);
    if (!done) return true;
    issue.satisfiedDependencies ||= [];
    issue.satisfiedDependencies.push({ dependency: key, resolution: 'already_satisfied', requirementsChecked: done.requirementsChecked });
    return false;
  });
}
return [{ json: { ...data, plan, personalRequirementsRequired: true, personalEvidenceKeys: keys, completePersonalEvidence,
  personalExpansion: { replacedKeys: [...removed], sourceRequirements: requirements } } }];

const HEADINGS = [
  '## Historia de Usuario',
  '## Contexto',
  '## Objetivo técnico',
  '## Alcance',
  '## Fuera de alcance',
  '## Archivos esperados',
  '## Pasos sugeridos',
  '## Criterios de aceptación',
  '## Pruebas',
  '## Dependencias',
  '## Evidencia individual',
  '## Definition of Done',
];

const asList = (value) => {
  if (!value) return [];
  return Array.isArray(value) ? value.filter(Boolean) : [String(value)];
};
const bullets = (value) => {
  const items = asList(value);
  return items.length ? items.map((item) => `- ${item}`).join('\n') : '- No aplica.';
};
const numbered = (value) => {
  const items = asList(value);
  return items.length ? items.map((item, index) => `${index + 1}. ${item}`).join('\n') : '1. No aplica.';
};
const paragraph = (value) => {
  if (!value) return 'No aplica.';
  return Array.isArray(value) ? value.join('\n') : String(value);
};
